      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks are a fundamental advance in precision measurement, combining exquisite control of atoms with an instrument of lasting scientific reach.",
        "attribution": "Katori and Ye are the central credited pioneers of the lattice-clock concept and its realization.",
        "maturity": "The clocks have been independently developed, repeatedly benchmarked, and are now a mature international field.",
        "uncertainties": []
      }
    },
    {
      "rank": 2,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry made quantum phase a practical precision probe of gravity, rotation, and fundamental physics.",
        "attribution": "Bordé supplied foundational atom-optics ideas, while Kasevich was central to decisive precision implementations; the full historical allocation remains broad.",
        "maturity": "The methods have been reproduced extensively and have become a durable platform for measurements and quantum sensing.",
        "uncertainties": [
          "The contribution is distributed among several foundational experimental and theoretical groups."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric phase and the Aharonov-Bohm effect transformed the understanding of phase, gauge structure, and observables in quantum mechanics.",
        "attribution": "Berry and Aharonov are unmistakably associated with the named conceptual advances, though their effects have distinct histories.",
        "maturity": "Both effects have received a vast range of experimental confirmations and have influenced atomic, condensed-matter, and optical physics.",
        "uncertainties": [
          "Combining the Aharonov-Bohm and Berry-phase contributions into one prize would require a particularly coherent formulation."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin",
        "Mark Saffman"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade revealed a striking controllable interaction between individual atoms and enabled a powerful many-body quantum platform.",
        "attribution": "Saffman made decisive foundational contributions, while Lukin and Browaeys have been leading experimental architects of programmable neutral-atom arrays.",
        "maturity": "Independent laboratories now achieve coherent many-atom control and use these systems for simulation and computation.",
        "uncertainties": [
          "The technology is advancing rapidly, so its ultimate scientific and computational impact is still developing."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B027",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold molecules opened unusually rich control of molecular quantum structure, collisions, chemistry, and symmetry tests.",
        "attribution": "DeMille, Doyle, and Ye each made major and identifiable contributions to producing and controlling cold molecules.",
        "maturity": "The field is experimentally robust and has grown from difficult demonstrations to broadly used methods.",
        "uncertainties": [
          "Credit is necessarily selective in a field with several important routes to ultracold molecules."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their proposals gave quantum information a concrete atomic-physics language for entangling ions and simulating many-body Hamiltonians.",
        "attribution": "Cirac and Zoller are the clear authors of several seminal theoretical schemes and their partnership is unusually well defined.",
        "maturity": "The concepts have been tested across trapped-ion and optical-lattice platforms and deeply shaped present experiments.",
        "uncertainties": [
          "Theoretical proposals overlap substantially with later experimental programs and related quantum-simulation candidates."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire and passive mode-locking supplied practical, stable femtosecond sources that changed ultrafast science.",
        "attribution": "Moulton, Keller, and Sibbett have substantial distinct claims in the laser medium and ultrafast-source development.",
        "maturity": "The technology has had decades of replication and enabled much later attosecond and strong-field physics.",
        "uncertainties": [
          "The credit chain for femtosecond laser development is broad and may not reduce cleanly to three people."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg",
        "Andrew N. Cleland"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics made it possible to cool, measure, and coherently manipulate mechanical motion near its quantum limit.",
        "attribution": "Aspelmeyer, Kippenberg, and Cleland represent major complementary experimental routes, though several other contributors are important.",
        "maturity": "Quantum control of mechanical systems is well established, with compelling experiments across optical and microwave devices.",
        "uncertainties": [
          "The field's most fundamental applications and a uniquely delimited attribution remain less settled than for the higher-ranked candidates."
        ]
      }
    }
  ]
